<template>
    <layout :options="getLayoutOptions()" class="les">
        <template #west>
            <tab :options="westOptions" class="les-tab" ref="les-west-tab"></tab>
        </template>
        <template #east>
            <lesEastBody/>
        </template>
        <template #center>
            <lesCenterBody></lesCenterBody>
        </template>
    </layout>
</template>

<script>
import Gikam from "../../../../../core/gikam-core.js";
import layout from "../../../../template/layout.vue";
import lesCenterBody from "../center/lesBody.vue";
import tab from "../../../../template/tab.vue";
import lesEastBody from '../templates/lesEastBody.vue';

export default {
    name: "les",
    components: { 
        layout, 
        lesCenterBody,
        tab,
        lesEastBody
    },

    data() {
        return {
            westOptions: {
                id: 'les-weat-tab',
                show: true,
                showIndex: 0,
                fill: true,
                panels: [
                    {
                        id: 'section', 
                        title: '章节',
                        items: [{
                            type: 'tree',
                            id: 'les-tree',
                            edit: false,
                            onNodeSelected: nodeId => {
                                Gikam.alert(nodeId)
                            },
                            data : [
                                {
                                    text: '组件1',
                                    id: 'les-01'
                                },
                                {
                                    text: '组件2',
                                    id: 'les-02'
                                }
                            ]
                        }]
                    },
                    {
                        id: 'annex', 
                        title: '附件',
                        type: 'tree',
                        panels: []
                    },
                ]
            },
            eastOptions: {
                id: 'les-east-tab',
                show: true,
                showIndex: 0,
                panels: [
                    {
                        id: 'section', 
                        title: '富文本',
                        type: 'tree',
                        panels: [{
                            
                        }]
                    }
                ]
            }
        }
    },

    provide() {
        return {
            tab: this
        }
    },

    mounted() {
        this.initTab('les-west-tab', this.westOptions.panels);
    },

    methods: {
        trigger: Gikam.emptyFunction,

        getLayoutOptions() {
            return {
                north: { height: 0 },
                west: {
                    width: "200px",
                    padding: '0 0 8px 8px',
                    resize: true
                },
                east: {
                    width: "200px",
                    padding: '8px 8px 8px 0',
                    resize: true
                },
                south: {
                    height: 0
                },
                center: {}
            };
        },

        initTab(ref, data) {
            const tabPanes = this.$refs[ref].$el.querySelectorAll('.tab-pane');
            data.forEach((tabPaneItem, index) => {
                if (!tabPaneItem.items) {
                    tabPaneItem.items = [];
                }
                tabPaneItem.items.forEach((item) => {
                    item.renderTo = tabPanes[index];
                    Gikam.create(item.type, item);
                });
            });
        },
    }
};
</script>

<style scoped>
.les .west > .body > .les-tab {
    padding: 0;
}

.les .west > .body > .les-tab >>> .tab-switch-icon {
    display: none;
}

.les .west > .body > .les-tab >>> .tree {
    padding: 0;
}

.les .west > .body > .les-tab >>> .tree > .tree-container {
    border: none;
}

.les .west > .body > .les-tab >>> .tree > .tree-container > .tree-header {
    display: none;
}

.les .west > .body > .les-tab >>> .tree > .tree-container > .tree-header > .tree-body {
    height: 100%;
}

.les .west > .body > .les-tab >>> ul.tab-header {
    border-bottom: 1px solid #eee;
}

.les .west > .body > .les-tab >>> ul > li {
    border-bottom: none;
}
</style>