<template>
    <div class="template-name" @click="activeSelectedState" :class="stateClassObject">
        <template v-if="editing">
            <div class="editor">
                <input :value="name" ref="input" />
            </div>
            <saveToolbar @click="saveToolbarClickHandle"></saveToolbar>
        </template>

        <template v-else>
            <div class="readonly-text">{{name}}</div>
            <div v-if="selected" class="selected-toolbar">
                <div class="btn" @click="activeEditor">
                    <editImg v-bind="{color:'#29cf68',width:'22px',height:'22px'}" />
                </div>
            </div>
        </template>
    </div>
</template>

<script>
import baseLesComp from "./baseLesComp";
import saveToolbar from "./saveToolbar";

export default {
    extends: baseLesComp,

    components: {
        saveToolbar
    },

    props: {
        propName: String
    },

    data() {
        return {
            name: this.propName
        };
    },

    computed: {
        textInputOptions() {
            return {
                options: {},
                propValue: this.name,
                propInvisible: !this.editing
            };
        }
    },

    methods: {
        save() {
            this.name = this.$refs.input.value;
        },

        //激活编辑器之后事件
        onAfterActiveEditor() {
            this.$refs.input.focus();
        }
    }
};
</script>

<style scoped>
.template-name {
    height: 30px;
    border-bottom: 1px solid #eee;
    background-color: #fafafa;
}

.template-name .readonly-text {
    font-size: 14px;
    font-family: "MicrosoftYaHei";
    color: rgba(0, 0, 0, 0.65);
    font-weight: 600;
    line-height: 30px;
    padding-left: 16px;
}

.editor {
    height: 30px;
    display: flex;
    align-items: center;
}

.editor input {
    border: none;
    height: 100%;
    width: 100%;
    padding-left: 5px;
}
</style>
