<script>
export default {
    data() {
        return {
            //是否选中
            selected: false,
            //是否处于编辑中
            editing: false
        };
    },

    computed: {
        stateClassObject() {
            return [
                "les-comp",
                {
                    selected: this.selected
                }
            ];
        }
    },

    watch: {},

    methods: {
        activeSelectedState() {
            this.selected = true;
        },

        activeEditor() {
            this.selected = false;
            this.editing = true;
            this.$nextTick(() => {
                //激活编辑器之后的事件
                this.onAfterActiveEditor && this.onAfterActiveEditor();
            });
        },

        saveToolbarClickHandle(type) {
            this.selected = true;
            this.editing = false;
            if (type === "confirm") {
                this.save();
            }
        }
    }
};
</script>

<style >
.les-comp {
    position: relative;
}
</style>